const React = window.React
const { useState, useEffect, useRef } = React

const API = 'http://localhost:3000/api'

export default function App() {
  const [tasks, setTasks] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [selectedTask, setSelectedTask] = useState(null)

  useEffect(() => {
    fetch(`${API}/tasks`)
      .then((r) => r.json())
      .then((data) => {
        setTasks(data)
        setLoading(false)
      })
      .catch((err) => {
        setError(err.message)
        setLoading(false)
      })
  }, [])

  if (loading) return <div>Загрузка...</div>
  if (error) return <div>Ошибка: {error}</div>

  if (selectedTask) {
    return (
      <ActForm
        task={selectedTask}
        onClose={() => setSelectedTask(null)}
      />
    )
  }

  return (
    <div style={{ padding: 20 }}>
      <h1>АктОффлайн</h1>
      <h2>Задания</h2>
      {tasks.length === 0 && <p>Заданий нет</p>}
      <ul>
        {tasks.map((task) => (
          <li key={task.id} style={{ marginBottom: 10 }}>
            {task.address} — {task.clientName} ({task.status})
            <button
              onClick={() => setSelectedTask(task)}
              style={{ marginLeft: 10 }}
            >
              Заполнить акт
            </button>
          </li>
        ))}
      </ul>
    </div>
  )
}

function ActForm({ task, onClose }) {
  const [clientFio, setClientFio] = useState(task.clientName)
  const [works, setWorks] = useState('')
  const [amount, setAmount] = useState('')
  const [saving, setSaving] = useState(false)
  const [message, setMessage] = useState('')
  
  // Ссылки для рисования
  const canvasRef = useRef(null)
  const isDrawing = useRef(false)

  // Функции для рисования
  const startDrawing = (e) => {
    isDrawing.current = true
    const canvas = canvasRef.current
    const ctx = canvas.getContext('2d')
    const rect = canvas.getBoundingClientRect()
    
    // Поддержка мыши и тача
    const x = (e.clientX || e.touches[0].clientX) - rect.left
    const y = (e.clientY || e.touches[0].clientY) - rect.top
    
    ctx.beginPath()
    ctx.moveTo(x, y)
  }

  const draw = (e) => {
    if (!isDrawing.current) return
    const canvas = canvasRef.current
    const ctx = canvas.getContext('2d')
    const rect = canvas.getBoundingClientRect()
    
    const x = (e.clientX || e.touches[0].clientX) - rect.left
    const y = (e.clientY || e.touches[0].clientY) - rect.top
    
    ctx.lineTo(x, y)
    ctx.stroke()
  }

  const stopDrawing = () => {
    isDrawing.current = false
  }

  const clearCanvas = () => {
    const canvas = canvasRef.current
    const ctx = canvas.getContext('2d')
    ctx.clearRect(0, 0, canvas.width, canvas.height)
  }

  const handleSave = async () => {
    if (!clientFio || !works || !amount) {
      setMessage('Заполните все поля')
      return
    }

    const canvas = canvasRef.current
    // Проверка, что холст не пустой
    const blank = document.createElement('canvas')
    blank.width = canvas.width
    blank.height = canvas.height
    if (canvas.toDataURL() === blank.toDataURL()) {
      setMessage('Поставьте подпись')
      return
    }

    const signatureBase64 = canvas.toDataURL('image/png')
    const act = {
      taskId: task.id,
      clientFio,
      works: [{ description: works }],
      totalAmount: Number(amount),
      signatureBase64,
      createdAt: new Date().toISOString(),
    }

    setSaving(true)
    setMessage('')

    if (navigator.onLine) {
      try {
        await fetch(`${API}/acts`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(act),
        })
        setMessage('Акт сохранён на сервере')
      } catch (e) {
        saveOffline(act)
        setMessage('Нет связи с сервером. Акт сохранён офлайн.')
      }
    } else {
      saveOffline(act)
      setMessage('Нет интернета. Акт сохранён офлайн.')
    }
    setSaving(false)
  }

  const saveOffline = (act) => {
    const queue = JSON.parse(localStorage.getItem('offlineActs') || '[]')
    queue.push(act)
    localStorage.setItem('offlineActs', JSON.stringify(queue))
  }

  return (
    <div style={{ padding: 20 }}>
      <button onClick={onClose}>← Назад к списку</button>
      <h2>Акт по заданию</h2>
      <p>
        <strong>Адрес:</strong> {task.address}
      </p>

      <div style={{ marginBottom: 10 }}>
        <label>ФИО клиента</label>
        <br />
        <input
          value={clientFio}
          onChange={(e) => setClientFio(e.target.value)}
          style={{ width: 300 }}
        />
      </div>

      <div style={{ marginBottom: 10 }}>
        <label>Перечень работ</label>
        <br />
        <textarea
          value={works}
          onChange={(e) => setWorks(e.target.value)}
          style={{ width: 300, height: 60 }}
        />
      </div>

      <div style={{ marginBottom: 10 }}>
        <label>Сумма</label>
        <br />
        <input
          type="number"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
          style={{ width: 300 }}
        />
      </div>

      <div style={{ marginBottom: 10 }}>
        <label>Подпись клиента (рисуйте мышкой или пальцем)</label>
        <div
          style={{
            border: '1px solid #000',
            width: 300,
            height: 150,
            background: '#fafafa'
          }}
        >
          <canvas
            ref={canvasRef}
            width={300}
            height={150}
            onMouseDown={startDrawing}
            onMouseMove={draw}
            onMouseUp={stopDrawing}
            onMouseLeave={stopDrawing}
            onTouchStart={startDrawing}
            onTouchMove={draw}
            onTouchEnd={stopDrawing}
            style={{ touchAction: 'none' }}
          />
        </div>
        <button onClick={clearCanvas} style={{ marginTop: 5 }}>
          Очистить подпись
        </button>
      </div>

      <button onClick={handleSave} disabled={saving} style={{ marginTop: 20 }}>
        {saving ? 'Сохранение...' : 'Сохранить акт'}
      </button>

      {message && <p style={{ color: 'green', fontWeight: 'bold' }}>{message}</p>}
    </div>
  )
}
